from typing import Any, Iterable


def flatten(items: Iterable[Any]) -> list:
    """Flatten nested lists/tuples into one list, preserving order. Strings are not split."""
    out: list = []
    stack = [iter(items)]
    while stack:
        for item in stack[-1]:
            if isinstance(item, (list, tuple)):
                stack.append(iter(item))
                break
            out.append(item)
        else:
            stack.pop()
    return out

