import functools
import time
from typing import Callable, Tuple, Type


def retry(times: int = 3, base_delay: float = 0.5, exceptions: Tuple[Type[BaseException], ...] = (Exception,),
          sleep: Callable[[float], None] = time.sleep):
    """Retry the wrapped function up to `times` attempts, doubling the delay after each failure."""
    if times < 1:
        raise ValueError("times must be >= 1")

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(1, times + 1):
                try:
                    return fn(*args, **kwargs)
                except exceptions:
                    if attempt == times:
                        raise
                    sleep(delay)
                    delay *= 2
        return wrapper
    return decorator

tests:
def test_succeeds_after_failures():
    calls, delays = [], []

    @retry(times=3, base_delay=1, sleep=delays.append)
    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise IOError("boom")
        return "ok"

    assert flaky() == "ok"
    assert delays == [1, 2]

def test_gives_up():
    @retry(times=2, base_delay=0, sleep=lambda s: None)
    def always_fails():
        raise ValueError("nope")

    try:
        always_fails()
        assert False
    except ValueError:
        pass

