import re


def rle_encode(text: str) -> str:
    """Encode runs as <char><count>."""
    if not text:
        return ""
    out, prev, count = [], text[0], 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{prev}{count}")
            prev, count = ch, 1
    out.append(f"{prev}{count}")
    return "".join(out)


def rle_decode(encoded: str) -> str:
    return "".join(ch * int(n) for ch, n in re.findall(r"(\D)(\d+)", encoded))

